// rarity by piece type: boots/limb pieces common, weapons & shields rare, helmets epic, chest/wings legendary
export const POOL = ARMOR.map((a, i) => ({
  r: a.r,
  name: a.name,
  set: a.set,
  spr: i,
  k: ARMOR.slice(0, i).filter((b) => b.set === a.set).length,
}));
